from collections import Counter, deque

def infer_transform(grid):
    h,w=len(grid),len(grid[0])
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    out=[row[:] for row in grid]
    seen=set(); comps=[]
    for r in range(h):
      for c in range(w):
        if grid[r][c]==bg or (r,c) in seen: continue
        color=grid[r][c]; q=[(r,c)]; seen.add((r,c)); cells=[]
        while q:
          y,x=q.pop(); cells.append((y,x))
          for ny,nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
            if 0<=ny<h and 0<=nx<w and (ny,nx) not in seen and grid[ny][nx]==color:
              seen.add((ny,nx));q.append((ny,nx))
        comps.append((color,cells))
    filled=set()
    for color,cells in comps:
      r0=min(r for r,c in cells);r1=max(r for r,c in cells);c0=min(c for r,c in cells);c1=max(c for r,c in cells)
      area=(r1-r0+1)*(c1-c0+1)
      if area>=4 and len(cells)/area>=0.70:
        for r in range(r0,r1+1):
          for c in range(c0,c1+1):
            out[r][c]=color;filled.add((r,c))
    for color,cells in comps:
      if len(cells)==1:
        r,c=cells[0]
        if (r,c) not in filled: out[r][c]=bg
    return out

